<?php $isEitaa=$channel==='eitaa';$states=['cancelled'=>'لغوشده؛ ارسال نمی‌شود','expired'=>'مهلت ارسال گذشته','pending'=>'در صف ارسال','sending'=>'در حال ارسال','sent'=>'پذیرفته‌شده توسط ایتا','provider_accepted'=>'پذیرفته‌شده توسط پیامک','rejected'=>'سرویس ارسال را نپذیرفت','provider_rejected'=>'پیامک پذیرفته نشد','unknown'=>'نتیجه نیازمند بررسی','unverified_response'=>'پاسخ سرویس نیازمند بررسی','submission_uncertain'=>'نتیجه نامشخص؛ تکرار نشده','permission_required'=>'نیازمند اجازهٔ مخاطب','not_linked'=>'اتصال مخاطب در دسترس نیست','disabled'=>'ارسال غیرفعال است']; ?>
<header class="admin-page-heading"><div><span class="eyebrow">ارتباط با مخاطبان مرشد</span><h1>مرکز پیام‌ها</h1><p class="muted">مخاطب را انتخاب کن، پیام بنویس و نتیجهٔ ارسال را ببین.</p></div><span class="tag"><?= $channelEnabled?'اتصال فعال':'نیازمند تنظیم اتصال' ?></span></header>
<nav class="messaging-tabs" aria-label="کانال ارسال پیام"><a class="secondary" <?= $isEitaa?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/messages?channel=eitaa')) ?>"><?= $this->icon('chat') ?>پیام ایتا</a><a class="secondary" <?= !$isEitaa?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/messages?channel=sms')) ?>"><?= $this->icon('chat') ?>پیامک TSMS</a></nav>
<div class="messaging-workspace"><section class="card"><h2>انتخاب مخاطبان</h2><p class="small muted"><?= $isEitaa?'افراد متصل به ایتا اینجا دیده می‌شوند. ارسال پیام دستی برای کسانی فعال است که اجازهٔ دریافت پیام را ثبت کرده‌اند.':'فقط حساب‌های فعال با شمارهٔ تأییدشده نشان داده می‌شوند. پیام‌های مرتبط با جلسه را برای مخاطب انتخاب‌شده بفرستید.' ?></p><form method="get" action="<?= $this->h($this->url('/messages')) ?>"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/messages"><?php endif; ?><input type="hidden" name="channel" value="<?= $channel ?>"><div class="search"><input type="search" name="q" maxlength="160" value="<?= $this->h(is_string($_GET['q']??null)?$_GET['q']:'') ?>" placeholder="جست‌وجوی نام، نام کاربری یا شماره" aria-label="جست‌وجوی مخاطب"><button class="secondary">جست‌وجو</button></div></form>
<?= $this->start('/messages/send') ?><input type="hidden" name="channel" value="<?= $channel ?>"><input type="hidden" name="request_id" value="<?= \Morshed\Core\Security::id() ?>"><div class="recipient-picker"><div class="recipient-toolbar"><input type="search" data-recipient-search placeholder="پیداکردن در این فهرست" aria-label="فیلتر همین فهرست"><span class="small muted" data-recipient-count>۰ مخاطب انتخاب شده</span></div><div class="recipient-list" data-recipient-list><?php foreach($contacts as $person):$selectable=!$isEitaa||!empty($person['eitaa_allowed']); ?><label class="recipient-row" data-recipient-row><input type="checkbox" name="user_ids[]" value="<?= $this->h($person['id']) ?>" <?= $selectable?'':'disabled' ?> <?= in_array($person['id'],$this->old['user_ids']??[],true)?'checked':'' ?>><span><strong><?= $this->h($person['display_name']?:($person['username']?:'حساب متصل به ایتا')) ?></strong><small><?= $this->h($person['username']?:'بدون نام کاربری') ?><?= !$isEitaa?' · '.$this->h($person['phone_hint']):'' ?></small></span><span class="tag"><?= $isEitaa?($selectable?'اجازهٔ پیام فعال':'منتظر اجازهٔ مخاطب'):'شماره تأییدشده' ?></span></label><?php endforeach; ?><?php if(!$contacts): ?><p class="empty muted">مخاطبی با این مشخصات پیدا نشد.</p><?php endif; ?></div></div><p class="small muted">در هر ارسال حداکثر ۲۰ مخاطب انتخاب کنید.</p><fieldset class="queue-mode"><legend>نحوهٔ ارسال</legend><label><input type="radio" name="send_mode" value="manual" <?= ($this->old['send_mode']??'manual')==='manual'?'checked':'' ?>>نگه‌داشتن در صف برای بازبینی</label><label><input type="radio" name="send_mode" value="immediate" <?= ($this->old['send_mode']??'')==='immediate'?'checked':'' ?>>ارسال فوری پس از ثبت در صف</label><label><input type="radio" name="send_mode" value="scheduled" <?= ($this->old['send_mode']??'')==='scheduled'?'checked':'' ?>>ارسال زمان‌بندی‌شده</label><label>روز و ساعت ارسال · به وقت تهران<input type="datetime-local" name="send_at" value="<?= $this->h($this->old['send_at']??'') ?>" data-send-at></label></fieldset><?= $this->field('title','عنوان پیام','text','',true,180) ?><label>متن پیام<textarea name="body" rows="5" maxlength="1000" required placeholder="مثلاً: جلسهٔ مشاورهٔ شما روز … ساعت … برگزار می‌شود."><?= $this->val('body') ?></textarea></label><button <?= $channelEnabled?'':'disabled' ?>>ثبت پیام برای مخاطبان انتخاب‌شده</button></form>
<nav class="row section" aria-label="صفحه‌بندی مخاطبان"><?php $q=is_string($_GET['q']??null)?$_GET['q']:'';if($recipientPage>1): ?><a class="secondary" href="<?= $this->h($this->url('/messages?'.http_build_query(['channel'=>$channel,'q'=>$q,'page'=>$recipientPage-1]))) ?>">مخاطبان قبلی</a><?php endif; ?><span class="small muted">صفحه <?= $this->number($recipientPage) ?></span><?php if($hasMore): ?><a class="secondary" href="<?= $this->h($this->url('/messages?'.http_build_query(['channel'=>$channel,'q'=>$q,'page'=>$recipientPage+1]))) ?>">مخاطبان بعدی</a><?php endif; ?></nav></section>
<aside class="card queue-panel" data-message-queue data-channel="<?= $channel ?>" data-process="<?= $this->h($this->url('/api/v1/messages/process')) ?>" data-csrf="<?= $this->h($this->csrf) ?>" data-auto="<?= $channelEnabled&&($_GET['dispatch']??'')==='1'?'1':'0' ?>"><div class="section-head"><h2>صف و نتیجهٔ ارسال‌ها</h2><span class="tag"><?= $this->number(count($rows)) ?> مورد اخیر</span></div><p class="small muted">لغو فقط تا پیش از شروع ارسال ممکن است. پیام‌های زمان‌بندی‌شدهٔ آینده با «ارسال همه» زودتر ارسال نمی‌شوند.</p><p class="notice small"><?= !empty($workerActive)?'اجرای پردازشگر در سه دقیقهٔ اخیر ثبت شده است.':'پردازش دقیقه‌ای هاست هنوز تأیید نشده؛ ارسال سرِ زمان بدون بازبودن صفحه به فعال‌بودن Cron وابسته است.' ?></p><?php if(empty($workerActive)): ?><details class="queue-cron"><summary>تنظیم پردازش دقیقه‌ای در Cron Jobs سی‌پنل</summary><p class="small">اجرای هر دقیقه، فقط یک پردازشگر هم‌زمان. پس از اولین اجرای موفق، وضعیت بالا فعال می‌شود.</p><code dir="ltr"><?= $this->h(escapeshellarg(PHP_BINDIR.'/php').' '.escapeshellarg(dirname(__DIR__).'/bin/messages-worker.php').' > /dev/null 2>&1') ?></code></details><?php endif; ?><?= $this->start('/messages/release-all') ?><input type="hidden" name="channel" value="<?= $channel ?>"><button <?= $channelEnabled?'':'disabled' ?>>ارسال تمامی پیام‌های آمادهٔ صف</button></form><p class="small" data-queue-progress role="status"></p><button class="secondary" type="button" data-queue-run <?= $channelEnabled?'':'disabled' ?>>ادامهٔ ارسال پیام‌های آماده</button><div class="queue-history section"><?php foreach($rows as $row):$waiting=$row['state']==='pending';$manual=($row['mode']??'')==='manual';$scheduled=($row['mode']??'')==='scheduled'; ?><article class="queue-item"><div class="section-head"><strong><?= $this->h($row['display_name']?:'کاربر مرشد') ?></strong><span class="tag"><?= $this->h($waiting?($manual?'منتظر دستور ارسال':($scheduled?'زمان‌بندی‌شده':'آمادهٔ ارسال')):($states[$row['state']]??'نیازمند بررسی')) ?></span></div><p><?= $this->h($row['title']) ?></p><?php if($scheduled&&$waiting): ?><p class="small muted">زمان ارسال: <time data-timestamp="<?= (int)$row['send_after'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$row['send_after'])) ?></time></p><?php endif; ?><div class="queue-actions"><?php $actions=$waiting?['release'=>'ارسال همین پیام','cancel'=>'لغو ارسال']:($row['state']==='permission_required'?['cancel'=>'لغو ارسال']:($row['state']==='cancelled'?['restore'=>'بازگرداندن به صف']:[]));foreach($actions as $action=>$label): ?><?= $this->start('/messages/queue') ?><input type="hidden" name="channel" value="<?= $channel ?>"><input type="hidden" name="id" value="<?= $this->h($row['notification_id']) ?>"><input type="hidden" name="action" value="<?= $action ?>"><button class="secondary" <?= $action==='release'&&!$channelEnabled?'disabled':'' ?>><?= $label ?></button></form><?php endforeach; ?></div></article><?php endforeach;if(!$rows): ?><p class="muted empty">هنوز پیامی در این کانال ثبت نشده است.</p><?php endif; ?></div><p class="small muted">پذیرش سرویس به‌تنهایی تضمین رسیدن پیام به دستگاه مخاطب نیست. لغو ارسال بیرونی، سابقه و اعلان داخل حساب را حذف نمی‌کند.</p></aside></div>
